#include <vector>

class Solution {
public:
    int countGoodCyclicRotations(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 1;

        std::vector<int> drops(2 * n - 1, 0);
        for (int i = 0; i < 2 * n - 1; ++i) {
            if (nums[i % n] > nums[(i + 1) % n]) drops[i] = 1;
        }

        int curr_drops = 0;
        for (int i = 0; i < n - 1; ++i) curr_drops += drops[i];
        int good = (curr_drops <= 1) ? 1 : 0;

        for (int i = 1; i < n; ++i) {
            curr_drops += drops[i + n - 2] - drops[i - 1];
            if (curr_drops <= 1) good++;
        }
        return good;
    }
};

